        CombatItemTaskEntity.sound(server, player.position(), "minecraft:entity.item.pickup", 1, 1);
        server.sendParticles(RemainingCombatContent.ICE_BOMB_EFFECT.get(), player.getX(), player.getY(), player.getZ(), 1, .001, .001, .001, 0);
        return result;
    }
